import {sampleData,calculate,metrics,metricValue,forecast,ageInvoices,recordPayment,addInvoice,parseCSV,validateMonths,validateInvoices,csv,numericFields,cashflows,endDate,iso} from './finance.js';
let data=sampleData(),period=data.months.at(-1).month,mode='month',route='overview',statement='income',ledgerFilter='all',query='',kpiGroup='All',modalReturn=null,pendingImport=null;
let scenario={...data.scenario},chat=[],selectedMetric='revenue',reportType='management';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',statements:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',cashflow:'M3 7h17l-4-4M21 17H4l4 4M20 7l-4 4M4 17l4-4',receivables:'M4 4h16v16H4zM8 12h8M12 8v8',payables:'M4 4h16v16H4zM8 12h8',budgets:'M4 19h16M6 16V9M12 16V4M18 16v-6',kpis:'M4 17l5-6 5 3 6-10M16 4h4v4',insights:'M9 18h6M10 21h4M8 14a7 7 0 1 1 8 0l-1 2H9z',assistant:'M4 4h16v13H9l-5 4zM8 8h8M8 12h5',reports:'M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h6',data:'M4 5c0-4 16-4 16 0s-16 4-16 0v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0'};
const links=[['overview','Overview'],['statements','Financial statements'],['cashflow','Cash flow'],['receivables','Receivables'],['payables','Payables'],['budgets','Budgets & forecasts'],['kpis','KPI library'],['insights','Insights & actions'],['assistant','Finance assistant'],['reports','Reports'],['data','Data & imports']];
const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[id]}"/></svg>`;
const amount=(n,compact=false)=>n===null||n===undefined||!Number.isFinite(n)?'N/A':new Intl.NumberFormat('en',{style:'currency',currency:data.currency,maximumFractionDigits:compact?1:0,notation:compact?'compact':'standard',currencyDisplay:'code'}).format(n);
const num=(n,d=1)=>n===null||n===undefined||!Number.isFinite(n)?'N/A':new Intl.NumberFormat('en',{maximumFractionDigits:d}).format(n);
const fmt=(n,f='money',compact=false)=>n===null||n===undefined||!Number.isFinite(n)?'N/A':f==='percent'?`${num(n*100)}%`:f==='ratio'?`${num(n,2)}×`:f==='days'?`${num(n)} days`:f==='months'?`${num(n)} months`:amount(n,compact);
const monthName=s=>new Date(s+'-01T00:00:00Z').toLocaleDateString('en',{month:'short',year:'numeric',timeZone:'UTC'});
const current=()=>calculate(data,period,mode),latest=()=>calculate(data,data.months.at(-1).month,'month');
const btn=(label,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(label,type='')=>`<span class="pill ${type}">${esc(label)}</span>`;
const metricBy=id=>metrics.find(m=>m.id===id);
function heading(title,sub='',tools=true){return `<div class="page-heading"><div><p class="eyebrow">FINANCIAL INTELLIGENCE</p><h1>${esc(title)}</h1><p>${esc(sub||`${data.company} · ${data.source} · ${mode==='ytd'?'Year to date through ':''}${monthName(period)}`)}</p></div>${tools?`<div class="page-tools"><select id="period" aria-label="Reporting month">${data.months.map(m=>`<option ${m.month===period?'selected':''} value="${m.month}">${monthName(m.month)}</option>`).reverse().join('')}</select><select id="mode" aria-label="Reporting range"><option value="month" ${mode==='month'?'selected':''}>Monthly</option><option value="ytd" ${mode==='ytd'?'selected':''}>Year to date</option></select>${btn('↓ Export','export-view','','primary')}</div>`:''}</div>`;}
function kpis(ids,v=current()){const i=data.months.findIndex(m=>m.month===period),previous=i>0?calculate(data,data.months[i-1].month,'month'):null;return `<div class="kpi-grid">${ids.map(id=>{const m=metricBy(id),value=metricValue(v,id),prev=previous?metricValue(previous,id):null,change=value!==null&&prev!==null&&prev!==0?(value-prev)/Math.abs(prev):null;const positive=m.good==='down'?change<0:change>0;return `<button class="card" data-action="metric" data-id="${id}"><span>${m.name}</span><span class="metric-arrow">↗</span><strong>${fmt(value,m.format,true)}</strong><small class="${change===null||mode==='ytd'||m.good==='neutral'?'':positive?'positive':'negative'}">${value===null?'Not applicable / data unavailable':mode==='month'&&change!==null?`${change>=0?'+':''}${num(change*100)}% vs previous month`:'Click to inspect calculation'}</small></button>`;}).join('')}</div>`;}
function lineChart(series,labels,height=265){const values=series.flatMap(s=>s.values).filter(Number.isFinite);if(!values.length)return '<div class="empty">No data available for this chart.</div>';const W=820,H=height,pad={l:64,r:20,t:16,b:42},min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1,y=v=>pad.t+(max-v)/range*(H-pad.t-pad.b),x=i=>pad.l+i*(W-pad.l-pad.r)/Math.max(1,labels.length-1);let body='';for(let i=0;i<5;i++){let v=min+range*i/4;body+=`<line x1="${pad.l}" x2="${W-pad.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e6ecee"/><text x="${pad.l-10}" y="${y(v)+4}" text-anchor="end">${num(v/1000,0)}k</text>`;}series.forEach(s=>{const points=s.values.map((v,i)=>Number.isFinite(v)?`${x(i)},${y(v)}`:null).filter(Boolean).join(' ');body+=`<polyline points="${points}" fill="none" stroke="${s.color}" stroke-width="3" ${s.dashed?'stroke-dasharray="7 5"':''}/>`;s.values.forEach((v,i)=>{if(Number.isFinite(v))body+=`<circle class="point" cx="${x(i)}" cy="${y(v)}" r="4" fill="${s.color}" tabindex="0" role="img" aria-label="${esc(`${labels[i]} ${s.name} ${amount(v)}`)}"><title>${esc(`${labels[i]} · ${s.name}: ${amount(v)}`)}</title></circle>`;});});labels.forEach((s,i)=>{if(labels.length<=7||i%2===0||i===labels.length-1)body+=`<text x="${x(i)}" y="${H-12}" text-anchor="middle">${esc(s)}</text>`;});return `<div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}${s.dashed?' (scenario)':''}</span>`).join('')}<span>${esc(data.currency)} · thousands</span></div><div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series.map(s=>s.name).join(' and '))} over time">${body}</svg></div>`;}
function bars(items,{percent=false}={}){const max=Math.max(1,...items.map(i=>Math.abs(i.value)));return items.map((i,j)=>`<div class="stat-line"><span>${esc(i.label)}</span><b>${percent?num(i.value)+'%':amount(i.value,true)}</b></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,Math.abs(i.value)/max*100))}%;background:${i.color||['#087770','#639e9b','#9bb5c4','#b4c9cf','#d5b66c'][j%5]}"></span></div>`).join('');}
function donut(items){const colors=['#087770','#85b9ae','#9cb1c5','#d9b86a'];const total=items.reduce((s,x)=>s+x.value,0);let offset=0;return `<div class="donut-area"><svg viewBox="0 0 180 180" role="img" aria-label="Cost breakdown"><circle cx="90" cy="90" r="62" fill="none" stroke="#edf1f3" stroke-width="20"/>${items.map((it,i)=>{const share=total?it.value/total:0,o=offset;offset+=share*389.56;return `<circle cx="90" cy="90" r="62" fill="none" stroke="${colors[i]}" stroke-width="20" stroke-dasharray="${share*389.56} 389.56" stroke-dashoffset="${-o}" transform="rotate(-90 90 90)"><title>${esc(it.label)}: ${amount(it.value)}</title></circle>`;}).join('')}<text x="90" y="84" text-anchor="middle" font-size="12" fill="#71838c">Total costs</text><text x="90" y="109" text-anchor="middle" font-size="21" font-weight="700" fill="#18323c">${num(total/1000,0)}k</text></svg><div class="donut-legend">${items.map((it,i)=>`<div><span><i style="display:inline-block;width:8px;height:8px;background:${colors[i]};margin-right:8px;border-radius:2px"></i>${esc(it.label)}</span><b>${total?num(it.value/total*100):0}%</b></div>`).join('')}</div></div>`;}
function statementTable(rows,v,{budget=false}={}){return `<div class="table-wrap"><table><thead><tr><th>Line item</th><th class="num">${mode==='ytd'?'Year to date':'Actual'} · ${data.currency}</th>${budget?'<th class="num">Budget</th><th class="num">Variance</th>':''}</tr></thead><tbody>${rows.map(([label,key,total,budgetKey])=>`<tr class="${total?'total':''}"><td>${esc(label)}</td><td class="num">${amount(v[key])}</td>${budget?`<td class="num">${budgetKey?amount(v[budgetKey]):'—'}</td><td class="num">${budgetKey?amount(v[key]-v[budgetKey]):'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
const incomeRows=[['Revenue','revenue',false,'budget_revenue'],['Cost of goods sold','cogs',false,'budget_cogs'],['Gross profit','gross_profit',true],['Operating expenses','opex',false,'budget_opex'],['EBITDA','ebitda',true],['Depreciation & amortization','depreciation'],['Operating profit','ebit',true],['Interest expense','interest'],['Income tax expense','income_tax'],['Net income','net_income',true]];
const balanceRows=[['Cash & equivalents','cash'],['Trade receivables','ar'],['Inventory','inventory'],['Other current assets','other_current_assets'],['Current assets','current_assets',true],['Net fixed assets','net_fixed_assets'],['Other non-current assets','other_assets'],['Total assets','total_assets',true],['Trade payables','ap'],['Taxes payable','taxes_payable'],['Short-term debt','short_debt'],['Other current liabilities','other_current_liabilities'],['Current liabilities','current_liabilities',true],['Long-term debt','long_debt'],['Total liabilities','total_liabilities',true],['Total equity','equity',true]];
const cashRows=[['Opening cash','opening_cash',true],['Customer collections','collections'],['Supplier payments','supplier_payments'],['Operating payments','operating_payments'],['Interest paid','interest_paid'],['Income tax paid','tax_paid'],['Operating cash flow','operating_cf',true],['Capital expenditure','capex'],['Asset sale proceeds','asset_sales'],['Investing cash flow','investing_cf',true],['Debt proceeds','debt_in'],['Equity contributions','equity_in'],['Principal repayments','debt_repayment'],['Dividends paid','dividends'],['Financing cash flow','financing_cf',true],['Net cash movement','net_cf',true],['Closing cash','cash',true]];
function getInsights(){const v=latest(),items=[];if(v.overdue_ar>0)items.push({id:'collections',title:`Prioritize ${amount(v.overdue_ar,true)} in overdue invoices`,detail:'Review the largest overdue balances and agree collection dates with customers.',route:'receivables',priority:'High',owner:'Finance'});if(v.opex_variance>0)items.push({id:'spending',title:`Operating spend is ${amount(v.opex_variance,true)} above budget`,detail:'Compare actual spending with the approved operating budget before changing the plan.',route:'budgets',priority:'Medium',owner:'Operations'});if(v.budget_attainment<1)items.push({id:'revenue',title:`Revenue is at ${num(v.budget_attainment*100)}% of target`,detail:`The gap is ${amount(-v.revenue_variance)}. Review the revenue trend and assumptions.`,route:'statements',priority:'Medium',owner:'Sales'});if(v.overdue_ap>0)items.push({id:'suppliers',title:`Review ${amount(v.overdue_ap,true)} of overdue supplier bills`,detail:'Check disputed bills and schedule payments against your cash position.',route:'payables',priority:'High',owner:'Finance'});if(v.operating_cf<0)items.push({id:'cash',title:'Operating activities are using cash',detail:'Inspect the cash-flow statement and test a slower-growth scenario.',route:'cashflow',priority:'High',owner:'Finance'});return items;}
function overview(){const v=current(),history=data.months.filter(m=>m.month<=period).slice(-6),ins=getInsights();return heading('Your business, in focus.')+kpis(['revenue','net_income','cash','operating_margin'])+`<div class="grid-2"><section class="card chart-card"><div class="section-heading"><h2>Revenue & operating costs</h2>${btn('Explore statements ↗','go','data-id="statements"','quiet small')}</div>${lineChart([{name:'Revenue',color:'#087770',values:history.map(x=>x.revenue)},{name:'COGS + OPEX',color:'#9aaec0',values:history.map(x=>x.cogs+x.opex)}],history.map(x=>monthName(x.month).slice(0,3)))}<div class="disclosure">Monthly values, regardless of the reporting range selected above.</div></section><section class="card"><div class="section-heading"><h2>Needs your attention</h2>${pill(ins.length+' insights','warn')}</div>${ins.slice(0,3).map((x,i)=>`<div class="action-row"><span class="action-number">0${i+1}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p>${btn('Review →','go',`data-id="${x.route}"`,'quiet small')}</div></div>`).join('')||'<div class="empty">No threshold alerts for the latest period.</div>'}<div class="disclosure">Alerts use the latest reporting month.</div></section></div><div class="grid-equal"><section class="card"><div class="section-heading"><h2>Where your revenue goes</h2>${btn('Cost ratios','metric','data-id="opex_ratio"','quiet small')}</div>${donut([{label:'Direct costs',value:v.cogs},{label:'Operating expenses',value:v.opex},{label:'D&A + interest',value:v.depreciation+v.interest},{label:'Income tax',value:v.income_tax}])}</section><section class="card"><div class="section-heading"><h2>Working capital</h2>${btn('View all KPIs','go','data-id="kpis"','quiet small')}</div>${bars([{label:'Receivables',value:v.ar},{label:'Inventory',value:v.inventory},{label:'Payables',value:v.ap}])}</section></div><div class="banner"><div><b>${esc(data.source)} · ${data.months.length} months available</b><p>Bring your own monthly financial data to recalculate every supported KPI.</p></div>${btn('Manage data sources','go','data-id="data"')}</div>`;}
function statementsView(){const v=current();return heading('Financial statements')+`<div class="tabs">${[['income','Income statement'],['balance','Balance sheet'],['cash','Cash-flow statement']].map(([id,n])=>btn(n,'statement',`data-id="${id}"`,id===statement?'active':'')).join('')}</div>`+kpis(statement==='income'?['gross_profit','ebitda','ebit','net_income']:statement==='balance'?['total_assets','total_liabilities','equity','working_capital']:['operating_cf','investing_cf','financing_cf','cash'])+`<section class="card"><div class="section-heading"><h2>${statement==='income'?'Profit & loss':statement==='balance'?'Financial position':'Cash movement'}</h2>${pill(statement==='balance'?(Math.abs(v.balance_check)<1?'Balanced':'Needs reconciliation'):statement==='cash'?(Math.abs(v.cash_check)<1?'Reconciled':'Needs reconciliation'):'Accrual basis','good')}</div>${statementTable(statement==='income'?incomeRows:statement==='balance'?balanceRows:cashRows,v,{budget:statement==='income'})}<p class="disclosure">${statement==='balance'?`At ${iso(endDate(period))}. Assets − liabilities − equity = ${amount(v.balance_check)}.`:statement==='cash'?'Payments are shown as positive outflows. Subtotals subtract payments. Interest paid is classified as operating.':'Expenses are shown as positive costs. Subtotals subtract the relevant costs. Income tax uses the recorded amount.'}</p></section>`;}
function cashflowView(){const v=current(),history=data.months.filter(m=>m.month<=period).slice(-6);return heading('Cash flow & liquidity')+kpis(['cash','operating_cf','free_cf','current_ratio'])+`<div class="grid-2"><section class="card chart-card"><div class="section-heading"><h2>Cash in, cash out</h2>${btn('90-day forecast ↗','go','data-id="budgets"','quiet small')}</div>${lineChart([{name:'Collections',color:'#087770',values:history.map(x=>x.collections)},{name:'Operating outflows',color:'#d2a557',values:history.map(x=>x.supplier_payments+x.operating_payments+x.interest_paid+x.tax_paid)},{name:'Closing cash',color:'#788eae',values:history.map(x=>cashflows(x).close)}],history.map(x=>monthName(x.month).slice(0,3)))}</section><section class="card"><div class="section-heading"><h2>Cash movement bridge</h2>${pill(data.currency)}</div><div class="stat-line"><span>Opening cash</span><b>${amount(v.opening_cash,true)}</b></div>${bars([{label:'Operating activities',value:v.operating_cf},{label:'Investing activities',value:v.investing_cf,color:'#d2a557'},{label:'Financing activities',value:v.financing_cf,color:'#8ca0b5'}])}<div class="stat-line"><strong>Closing cash</strong><strong>${amount(v.cash,true)}</strong></div><p class="disclosure">Bar lengths show absolute amounts; values retain their signs.</p></section></div>`+kpis(['quick_ratio','cash_ratio','burn','runway'])+`<section class="card"><div class="section-heading"><h2>Cash conversion cycle</h2>${btn('Inspect calculation','metric','data-id="ccc"','quiet small')}</div><div class="kpi-grid" style="margin:0">${['dso','dio','dpo','ccc'].map(k=>`<div><p class="muted">${metricBy(k).name}</p><strong>${fmt(v[k],'days')}</strong></div>`).join('')}</div><p class="disclosure">DSO + inventory days − payable days. Revenue and COGS are proxies for credit sales and purchases.</p></section>`;}
function ledgerView(kind){const name=kind==='receivable'?'Receivables':'Payables',list=data.invoices.filter(x=>x.kind===kind),filtered=list.filter(x=>{const balance=x.amount-x.paid,status=balance<.005?'paid':x.due<data.asOf?'overdue':'open';return (ledgerFilter==='all'||status===ledgerFilter)&&`${x.party} ${x.id}`.toLowerCase().includes(query.toLowerCase());}),total=list.reduce((a,x)=>a+x.amount-x.paid,0),overdue=list.filter(x=>x.due<data.asOf).reduce((a,x)=>a+x.amount-x.paid,0);return heading(name,`${data.company} · Latest ledger as of ${data.asOf}`,false)+`<div class="page-tools" style="margin-bottom:24px">${btn(kind==='receivable'?'+ Add invoice':'+ Add bill','add-invoice',`data-kind="${kind}"`,'primary')}${btn('↓ Export ledger','export-ledger',`data-kind="${kind}"`)}<select id="ledger-filter" aria-label="Invoice status">${['all','open','overdue','paid'].map(s=>`<option value="${s}" ${s===ledgerFilter?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select><input class="search-field" id="ledger-search" placeholder="Search name or invoice ID" aria-label="Search ledger" value="${esc(query)}"></div>${data.ledgerMatched===false?'<div class="banner"><div><b>Import a matching invoice ledger</b><p>Monthly totals are available; detailed aging requires a ledger matching those closing balances.</p></div>'+btn('Import ledger','go','data-id="data"')+'</div>':''}<div class="grid-2"><section class="card"><div class="section-heading"><h2>Outstanding ${kind==='receivable'?'customer balances':'supplier balances'}</h2>${pill(list.length+' records')}</div><div class="big-number">${amount(data.ledgerMatched===false?latest()[kind==='receivable'?'ar':'ap']:total)}</div><p class="muted">${data.ledgerMatched===false?'Monthly balance · ledger not loaded':`${amount(overdue)} overdue · ${list.filter(x=>x.paid>=x.amount).length} settled`}</p><div class="notice">Recording a ${kind==='receivable'?'receipt':'payment'} updates cash and ${kind==='receivable'?'receivables':'payables'}. This is bookkeeping only; no money is moved.</div></section><section class="card"><h2>Aging breakdown</h2>${data.ledgerMatched===false?'<p class="muted">Aging unavailable until a matching ledger is imported.</p>':bars(ageInvoices(data,kind))}</section></div><section class="card"><div class="table-wrap"><table><thead><tr><th>ID / party</th><th>Due date</th><th>Status</th><th class="num">Amount</th><th class="num">Outstanding</th><th class="num">Action</th></tr></thead><tbody>${filtered.map(x=>{const balance=x.amount-x.paid,status=balance<.005?'Paid':x.due<data.asOf?'Overdue':'Open';return `<tr><td><b>${esc(x.party)}</b><br><span class="tiny muted">${esc(x.id)}</span></td><td>${x.due}</td><td>${pill(status,status==='Paid'?'good':status==='Overdue'?'bad':'')}</td><td class="num">${amount(x.amount)}</td><td class="num">${amount(balance)}</td><td><div class="table-actions">${btn('Details','invoice',`data-id="${esc(x.id)}"`,'small')}${balance>.005?btn(kind==='receivable'?'Record receipt':'Record payment','payment',`data-id="${esc(x.id)}"`,'small primary'):''}</div></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">No matching records.</td></tr>'}</tbody></table></div></section>`;}
function budgetView(){const v=current(),f=forecast(data,scenario),base=latest(),lower=Math.min(...f.map(x=>x.closing));return heading('Budgets & forecasts')+kpis(['budget_attainment','revenue_variance','opex_variance','free_cf'])+`<div class="grid-2"><section class="card"><div class="section-heading"><h2>Next 3 months · cash forecast</h2>${pill('Assumption-based')}</div>${lineChart([{name:'Cash balance',color:'#087770',values:[base.cash,...f.map(x=>x.closing)],dashed:true}],[monthName(data.months.at(-1).month),...f.map(x=>monthName(x.month))])}<div class="grid-equal" style="margin:0"><div><p class="muted tiny">Projected closing cash</p><h2>${amount(f.at(-1).closing)}</h2></div><div><p class="muted tiny">Lowest projected month-end cash</p><h2 class="${lower<0?'negative':''}">${amount(lower)}</h2></div></div><p class="disclosure">Uses latest month, irrespective of the range above. A deterministic scenario, not a predictive AI model. Collections = revenue + opening receivables − target receivables, floored at zero. Target receivables = revenue × collection days ÷ 30. Interest, tax, capex and debt payments hold at the latest month. No within-month cash timing is modeled.</p></section><section class="card"><h2>Scenario assumptions</h2><form id="scenario-form" class="controls" style="margin-top:24px">${[['growth','Monthly revenue growth',-30,30,'%'],['cost','Monthly cost growth',-20,30,'%'],['collectionDays','Target collection time',0,90,' days']].map(([id,label,min,max,unit])=>`<label>${label}<output id="out-${id}">${scenario[id]}${unit}</output><input name="${id}" id="${id}" type="range" min="${min}" max="${max}" value="${scenario[id]}" data-unit="${unit}"></label>`).join('')}<button class="primary" type="submit">Recalculate forecast</button>${btn('Save scenario','save-scenario')}${btn('Reset assumptions','reset-scenario','','quiet small')}</form></section></div><section class="card"><div class="section-heading"><h2>Monthly budget editor</h2>${pill(monthName(period))}</div><form id="budget-form"><div class="table-wrap"><table><thead><tr><th>Budget line</th><th class="num">Actual</th><th class="num">Budget</th><th class="num">Variance</th></tr></thead><tbody>${[['Revenue','revenue','budget_revenue'],['Direct costs','cogs','budget_cogs'],['Operating expenses','opex','budget_opex']].map(([n,k,b])=>{const m=data.months.find(x=>x.month===period);return `<tr><td>${n}</td><td class="num">${amount(m[k])}</td><td class="num"><input class="budget-input" name="${b}" type="number" min="0" step="0.01" required value="${m[b]}" aria-label="${n} budget"></td><td class="num">${amount(m[k]-m[b])}</td></tr>`;}).join('')}</tbody></table></div><div class="report-actions"><button class="primary" type="submit">Save budget</button>${btn('Export forecast','export-forecast')}</div><p class="disclosure">Edits apply to ${monthName(period)} only. KPI cards follow the selected reporting range.</p></form></section>`;}
function kpiView(){const v=current(),groups=['All',...new Set(metrics.map(m=>m.group))],filtered=metrics.filter(m=>(kpiGroup==='All'||m.group===kpiGroup)&&`${m.name} ${m.id} ${m.description}`.toLowerCase().includes(query.toLowerCase()));return heading('Every metric, one place.',`${metrics.length} SME finance KPIs · Definitions, formulas and historical values`)+`<div class="filter-row"><input id="kpi-search" class="search-field" placeholder="Search revenue, liquidity, DSO…" aria-label="Search KPI library" value="${esc(query)}"><select id="kpi-group" aria-label="KPI category">${groups.map(g=>`<option ${g===kpiGroup?'selected':''}>${g}</option>`).join('')}</select>${pill(filtered.length+' metrics')}</div><div class="metric-catalog">${filtered.map(m=>`<button class="card catalog-card" data-action="metric" data-id="${m.id}">${pill(m.group)}<h3>${m.name}</h3><strong>${fmt(metricValue(v,m.id),m.format,true)}</strong><p>${m.formula}</p><span class="tiny positive">Definition & history ↗</span></button>`).join('')||'<div class="empty">No matching metrics.</div>'}</div>`;}
function insightView(){const ins=getInsights();return heading('From insight to action',`${data.company} · Rules calculated from the latest reporting month`,false)+(ins[0]?`<section class="insight-lead"><div><p class="eyebrow">PRIORITY INSIGHT</p><h2>${esc(ins[0].title)}</h2><p>${esc(ins[0].detail)}</p></div>${btn('Review supporting data','go',`data-id="${ins[0].route}"`,'primary')}</section>`:'')+`<div class="grid-equal"><section class="card"><h2>Suggested actions</h2>${ins.map((x,i)=>`<div class="action-row"><span class="action-number">0${i+1}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p><p>${pill(x.priority,x.priority==='High'?'warn':'')} · ${esc(x.owner)}</p>${btn(data.tasks.some(t=>t.key===x.id)?'Added to plan':'Add to action plan','add-task',`data-id="${x.id}" ${data.tasks.some(t=>t.key===x.id)?'disabled':''}`,'small')}${btn('Inspect data','go',`data-id="${x.route}"`,'quiet small')}</div></div>`).join('')||'<p class="muted">No threshold alerts.</p>'}<p class="disclosure">Suggestions come from visible budget and overdue-balance rules. They are prompts for human review.</p></section><section class="card"><div class="section-heading"><h2>Your action plan</h2>${pill(data.tasks.filter(t=>!t.done).length+' open')}</div>${data.tasks.map(t=>`<label class="check-row"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''}><span class="${t.done?'subdued':''}">${esc(t.title)}<br><small class="muted">${esc(t.owner)} · ${t.done?'Completed':'Open'}</small></span></label>`).join('')||'<div class="empty">Add a suggested action to start your plan.</div>'}${data.tasks.length?btn('Export action plan','export-tasks','','small'):''}<div class="notice">Tasks and edits stay in this session. Download a workspace backup to keep them.</div></section></div>`;}
function answer(q){const v=current(),s=q.toLowerCase();if(/why|reason|cause/.test(s)){if(/expense|cost|spend/.test(s)){const i=data.months.findIndex(m=>m.month===period);if(i<1)return 'There is no prior month available for a cost comparison.';const prev=calculate(data,data.months[i-1].month),delta=v.opex-prev.opex;return `Operating expenses are ${amount(v.opex)} for the selected range. On a monthly basis, ${monthName(period)} OPEX changed by ${amount(data.months[i].opex-prev.opex)} vs the previous month.\n\nThe monthly totals identify the change, but do not establish its cause. Upload transaction-level evidence elsewhere or review the underlying accounting records before attributing it to a supplier or department.`;}return 'The available monthly totals can show changes, but cannot establish causes. Try “revenue”, “cash flow”, “overdue invoices”, or a KPI name to inspect the evidence.';}
 if(/forecast|next (3|three|90)|scenario/.test(s)){const f=forecast(data,scenario);return `Using the current scenario (${scenario.growth}% monthly revenue growth, ${scenario.cost}% cost growth, ${scenario.collectionDays}-day collections), projected month-end cash is:\n${f.map(x=>`${monthName(x.month)}: ${amount(x.closing)}`).join('\n')}\n\nThis is an assumption-based scenario using the latest month. Change the assumptions in Budgets & forecasts.`;}
 if(/overdue|invoice|receivable|owe/.test(s)){if(data.ledgerMatched===false)return 'The current monthly file has no matching invoice ledger. Import the ledger to see overdue balances and customer-level detail.';const overdue=data.invoices.filter(x=>x.kind==='receivable'&&x.due<data.asOf&&x.amount>x.paid).sort((a,b)=>(b.amount-b.paid)-(a.amount-a.paid));return `As of ${data.asOf}, overdue receivables total ${amount(overdue.reduce((a,x)=>a+x.amount-x.paid,0))}.\n${overdue.slice(0,5).map(x=>`${x.party} · ${x.id}: ${amount(x.amount-x.paid)} · due ${x.due}`).join('\n')}\n\nOpen Receivables to inspect or record a receipt.`;}
 if(/summary|health|doing|overview/.test(s))return `${data.company} · ${mode==='ytd'?'YTD through ':''}${monthName(period)}\nRevenue: ${amount(v.revenue)}\nNet income: ${amount(v.net_income)} (${fmt(v.net_margin,'percent')} margin)\nCash balance: ${amount(v.cash)}\nOperating cash flow: ${amount(v.operating_cf)}\nCurrent ratio: ${fmt(v.current_ratio,'ratio')}\nRevenue target attainment: ${fmt(v.budget_attainment,'percent')}\n\nSource: ${data.source}. Use Financial statements to inspect the component amounts.`;
 const aliases=[[/cash flow|cashflow/,'operating_cf'],[/cash balance|cash position|how much cash/,'cash'],[/profit margin/,'net_margin'],[/net profit|profit/,'net_income'],[/expenses|spending/,'opex'],[/sales/,'revenue'],[/working capital/,'working_capital']];let m=metrics.filter(m=>s.includes(m.name.toLowerCase())||s===m.id.toLowerCase()).sort((a,b)=>b.name.length-a.name.length)[0];if(!m){const found=aliases.find(([rx])=>rx.test(s));if(found)m=metricBy(found[1]);}if(m)return `${m.name}: ${fmt(metricValue(v,m.id),m.format)}\nPeriod: ${mode==='ytd'?'YTD through ':''}${monthName(period)}\nFormula: ${m.formula}\n\n${m.description}\nSource: ${data.source}. Open the KPI library for history.`;return 'I could not map that question to the available financial data. I can report KPI values, summarize finances, list overdue invoices, compare operating expenses, or explain the current forecast. I do not browse external information or invent missing figures. Try a specific metric name from the KPI library.';
}
function assistantView(){return heading('Ask your financial data',`${data.company} · ${mode==='ytd'?'YTD through ':''}${monthName(period)} · ${data.source}`)+`<div class="chat-layout"><section class="card"><div class="section-heading"><h2>Finance data assistant</h2>${pill('Local • data-grounded')}</div><div class="chat-feed" id="chat-feed">${chat.length?chat.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?'<small>INSIGHTX · CALCULATED FROM YOUR WORKSPACE</small>':''}${esc(m.text)}</div>`).join(''):'<div class="message"><small>INSIGHTX</small>What would you like to understand? Ask about your revenue, cash, overdue invoices, a financial KPI, or the current forecast.</div>'}</div><form class="chat-form" id="chat-form"><input name="question" required maxlength="1000" placeholder="How is our business doing this month?" aria-label="Ask about financial data"><button class="primary" type="submit">Send ↑</button></form><p class="disclosure">This prototype uses a local financial query assistant, not a connected language model. Answers are limited to supported questions and the loaded data. Prior answers retain their original period.</p></section><aside class="chat-side card"><h2>Start with a question</h2>${['Give me a financial summary','How much cash do we have?','Which invoices are overdue?','Why did expenses change?','Show the next 3 months forecast','What is our cash conversion cycle?'].map(q=>btn(esc(q),'ask',`data-question="${esc(q)}"`,'suggestion')).join('')}${btn('Clear conversation','clear-chat','','quiet small')}<p class="disclosure">No data leaves this page when you ask a question.</p></aside></div>`;}
function reportsView(){const v=current();return heading('Reports')+`<div class="tabs">${[['management','Management summary'],['income','Profit & loss'],['balance','Balance sheet'],['cash','Cash-flow statement']].map(([id,n])=>btn(n,'report-type',`data-id="${id}"`,reportType===id?'active':'')).join('')}</div><div class="page-tools" style="margin-bottom:22px">${btn('Print / save PDF','print','','primary')}${btn('Download CSV','export-report')}${btn('Save snapshot','save-report')}</div><article class="card report-sheet"><div class="report-company"><p class="eyebrow">INSIGHTX FINANCE</p><h2>${esc(data.company)}</h2><p class="muted">${mode==='ytd'?'Year to date through ':''}${monthName(period)} · ${data.currency} · ${esc(data.source)}</p></div>${reportType==='management'?`<h2>Management summary</h2><div style="margin-top:24px">${kpis(['revenue','net_income','cash','working_capital'],v)}</div>${statementTable(incomeRows,v)}<h3 style="margin-top:24px">Key liquidity and working-capital measures</h3><p>Current ratio: ${fmt(v.current_ratio,'ratio')} · Cash conversion cycle: ${fmt(v.ccc,'days')} · Operating cash flow: ${amount(v.operating_cf)}</p>`:statementTable(reportType==='income'?incomeRows:reportType==='balance'?balanceRows:cashRows,v)}<p class="disclosure">Generated from the current workspace. Figures are unaudited. Reporting dates and sources are shown above.</p></article><section class="card" style="margin-top:24px"><h2>Saved report snapshots</h2>${data.savedReports.length?data.savedReports.map(r=>`<div class="action-row"><div style="flex:1"><h3>${esc(r.name)}</h3><p>${esc(r.created)}</p></div>${btn('Download','download-snapshot',`data-id="${esc(r.id)}"`,'small')}</div>`).join(''):'<p class="muted">Save a snapshot to preserve the current report values in this session.</p>'}</section>`;}
function dataView(){return heading('Data & imports','Your monthly figures power every statement, KPI, chart and forecast.',false)+`<div class="banner"><div><b>${esc(data.source)} · ${data.months.length} months · ${esc(data.company)}</b><p>Session-only workspace. Imported data is processed in your browser. Download a backup before closing.</p></div>${btn('Download workspace backup','backup','','primary')}</div><div class="grid-equal"><section class="card"><h2>Monthly financial data</h2><p class="muted">Import a CSV with monthly income, cash movements, closing balances and budgets.</p><p>${pill(data.months[0].month+' → '+data.months.at(-1).month)} ${pill('Balance checks passed','good')}</p><div class="report-actions">${btn('Import monthly CSV','import-months','','primary')}${btn('Download template','template-months')}</div><p class="disclosure">Required columns and example values are included in the template. Up to 120 consecutive months. Imports replace the current monthly dataset after review.</p>${btn('View column guide','column-guide','','quiet small')}</section><section class="card"><h2>Invoices & supplier bills</h2><p class="muted">Add detailed customer and supplier balances for aging and collection workflows.</p><p>${pill(data.ledgerMatched===false?'Matching ledger needed':data.invoices.length+' ledger records',data.ledgerMatched===false?'warn':'good')}</p><div class="report-actions">${btn('Import ledger CSV','import-ledger','','primary')}${btn('Download template','template-ledger')}</div><p class="disclosure">Outstanding receivables and payables must match the latest closing balances. This import provides detail and does not post new revenue or expenses.</p></section><section class="card"><h2>Workspace backup</h2><p class="muted">Keep your dataset, invoice updates, scenario, action plan and report snapshots.</p><div class="report-actions">${btn('Restore backup','restore')}${btn('Reset to sample company','reset','','quiet')}</div></section><section class="card"><h2>Company settings</h2><p class="muted">Set the company name and reporting currency label used throughout your workspace.</p>${btn('Edit company settings','settings')}<p class="disclosure">Currency changes update labels only; foreign-exchange conversion is not performed.</p></section></div><section class="card"><div class="section-heading"><h2>Activity log</h2>${btn('Export activity','export-audit','','small')}</div>${data.audit.slice(0,20).map(x=>`<div class="action-row"><span class="tiny muted">${esc(x.at.slice(0,19).replace('T',' '))}</span><span>${esc(x.action)}</span></div>`).join('')||'<p class="muted">No edits yet. Import or update data to see changes here.</p>'}</section>`;}
function render(){route=location.hash.slice(1)||'overview';if(!links.some(x=>x[0]===route))route='overview';$('#nav').innerHTML=links.map(([id,name],i)=>`${i===6?'<div class="nav-label">INTELLIGENCE</div>':i===10?'<div class="nav-label">WORKSPACE</div>':''}<a href="#${id}" class="${id===route?'active':''}" ${id===route?'aria-current="page"':''}><span class="nav-icon">${icon(id)}</span>${name}</a>`).join('');$('.company').innerHTML=`<b>${esc(data.company[0])}</b><div>${esc(data.company)}<small>Finance workspace · ${esc(data.currency)}</small></div>`;$('#breadcrumb').textContent='Workspace / '+links.find(x=>x[0]===route)[1];$('.sidebar-foot').innerHTML=`<span class="sample-dot"></span>${esc(data.source)}<small>Session-only · Download a backup</small>`;$('#content').innerHTML=({overview,statements:statementsView,cashflow:cashflowView,receivables:()=>ledgerView('receivable'),payables:()=>ledgerView('payable'),budgets:budgetView,kpis:kpiView,insights:insightView,assistant:assistantView,reports:reportsView,data:dataView})[route]();$('footer span').textContent=`${data.source} · No bank connection`;if(route==='assistant')$('#chat-feed').scrollTop=$('#chat-feed').scrollHeight;}
function go(id){query='';ledgerFilter='all';if(location.hash==='#'+id)render();else location.hash=id;$('.sidebar').classList.remove('open');}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function download(name,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,body){modalReturn=document.activeElement;$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${btn('×','close','aria-label="Close dialog"')}</div>${body}</section>`;$('#overlay').querySelector('input,select,button')?.focus();}
function close(){ $('#overlay').hidden=true;$('#overlay').innerHTML='';pendingImport=null;modalReturn?.focus();}
function metricHistoryChart(id,history){const m=metricBy(id),values=history.map(x=>metricValue(calculate(data,x.month),id));const finite=values.filter(Number.isFinite);if(!finite.length)return '<p class="muted">History unavailable for this metric.</p>';const low=Math.min(0,...finite),high=Math.max(1,...finite),x=i=>64+i*540/Math.max(1,history.length-1),y=v=>20+(high-v)/(high-low)*140;return `<div class="chart"><svg viewBox="0 0 640 210" role="img" aria-label="${esc(m.name)} monthly history"><line x1="64" y1="160" x2="610" y2="160" stroke="#e2e9ed"/><text x="4" y="25">${esc(fmt(high,m.format,true))}</text><text x="4" y="160">${esc(fmt(low,m.format,true))}</text><polyline fill="none" stroke="#087770" stroke-width="3" points="${values.map((v,i)=>Number.isFinite(v)?x(i)+','+y(v):'').filter(Boolean).join(' ')}"/>${values.map((v,i)=>Number.isFinite(v)?`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#087770"><title>${esc(monthName(history[i].month)+': '+fmt(v,m.format))}</title></circle>`:'').join('')}${history.map((h,i)=>`<text x="${x(i)}" y="195" text-anchor="middle">${monthName(h.month).slice(0,3)}</text>`).join('')}</svg></div>`;}
function metricModal(id){const m=metricBy(id);if(!m)return;const v=current(),history=data.months.filter(x=>x.month<=period).slice(-6);modal(m.name,`<div class="metric-detail"><strong class="big-number">${fmt(metricValue(v,id),m.format)}</strong>${pill(m.group)}</div><p class="muted">${mode==='ytd'?'Year to date through ':''}${monthName(period)}</p><p>${m.description}</p><div class="formula"><b>Formula</b><br>${m.formula}</div><h3 style="margin-top:24px">Monthly history</h3>${metricHistoryChart(id,history)}<div class="table-wrap"><table><thead><tr><th>Period</th><th class="num">Value</th></tr></thead><tbody>${history.map(x=>`<tr><td>${monthName(x.month)}</td><td class="num">${fmt(metricValue(calculate(data,x.month),id),m.format)}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">N/A indicates a zero denominator, a non-meaningful ratio, or unavailable ledger detail. Monthly history is not annualized.</p><div class="modal-footer">${btn('Download history','export-metric',`data-id="${id}"`)}${btn('Done','close','','primary')}</div>`);}
function invoiceModal(id){const inv=data.invoices.find(x=>x.id===id);modal(inv.id,`<dl><dt>Party</dt><dd>${esc(inv.party)}</dd><dt>Issued</dt><dd>${inv.issued}</dd><dt>Due</dt><dd>${inv.due}</dd><dt>Original amount</dt><dd>${amount(inv.amount)}</dd><dt>Paid</dt><dd>${amount(inv.paid)}</dd><dt>Outstanding</dt><dd>${amount(inv.amount-inv.paid)}</dd><dt>Notes</dt><dd>${esc(inv.notes||'No notes')}</dd></dl><div class="modal-footer">${btn('Download record','export-invoice',`data-id="${esc(id)}"`)}${inv.amount>inv.paid?btn('Record '+(inv.kind==='receivable'?'receipt':'payment'),'payment',`data-id="${esc(id)}"`,'primary'):''}</div>`);}
function paymentModal(id){const inv=data.invoices.find(x=>x.id===id);modal(`Record ${inv.kind==='receivable'?'receipt':'payment'}`,`<p><b>${esc(inv.party)}</b> · ${esc(id)}</p><p>Outstanding: ${amount(inv.amount-inv.paid)}</p><form id="payment-form" data-id="${esc(id)}"><label class="field">Amount (${data.currency})<input name="amount" type="number" min="0.01" max="${(inv.amount-inv.paid).toFixed(2)}" step="0.01" required value="${(inv.amount-inv.paid).toFixed(2)}"></label><p class="notice">Posts to the latest reporting month (${monthName(data.months.at(-1).month)}). Updates the ledger and cash totals only; this does not execute a bank transfer.</p><div id="form-error"></div><div class="modal-footer">${btn('Cancel','close')}<button class="primary" type="submit">Confirm entry</button></div></form>`);}
function invoiceForm(kind){if(data.ledgerMatched===false){toast('Import a matching ledger before posting new entries.');return;}modal(kind==='receivable'?'Add customer invoice':'Add supplier bill',`<form id="invoice-form" data-kind="${kind}"><div class="form-grid"><label class="field">Record ID<input name="id" required maxlength="60" value="${kind==='receivable'?'INV':'BILL'}-${Date.now().toString().slice(-7)}"></label><label class="field">${kind==='receivable'?'Customer':'Supplier'} name<input name="party" required maxlength="120"></label><label class="field">Amount (${data.currency})<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="field">Issue date<input name="issued" type="date" required value="${data.asOf}"></label><label class="field">Due date<input name="due" type="date" required value="${data.asOf}"></label><label class="field full">Notes<textarea name="notes" maxlength="500" rows="2"></textarea></label></div><div class="notice">This simplified entry recognizes ${kind==='receivable'?'revenue and receivables':'an operating expense and payables'} in the latest month. Amounts exclude VAT; use the monthly import for more complex accounting adjustments.</div><div id="form-error"></div><div class="modal-footer">${btn('Cancel','close')}<button class="primary" type="submit">Add ${kind==='receivable'?'invoice':'bill'}</button></div></form>`);}
function importModal(type){modal(type==='months'?'Import monthly financial CSV':type==='ledger'?'Import invoice ledger CSV':'Restore workspace backup',`<form id="import-form" data-type="${type}"><p class="muted">${type==='restore'?'Choose an InsightX JSON backup. Its monthly figures and invoice balances will be validated.':'Choose a UTF-8 CSV using the provided template. Required columns and balance checks are validated before replacing any data.'}</p><label class="field">Select file<input name="file" type="file" accept="${type==='restore'?'.json':'.csv'}" required></label><p class="disclosure">Maximum 5 MB. Files are processed locally in your browser.</p><div id="form-error"></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="primary">Validate & review</button></div></form>`);}
function settingsModal(){modal('Company settings',`<form id="settings-form"><div class="form-grid"><label class="field full">Company name<input name="company" maxlength="80" required value="${esc(data.company)}"></label><label class="field">Reporting currency<select name="currency">${['SAR','USD','AED','EUR','GBP'].map(c=>`<option ${c===data.currency?'selected':''}>${c}</option>`).join('')}</select></label></div><p class="notice">The currency is a reporting label. Changing it does not convert amounts. Keep it consistent with your imported data.</p><div class="modal-footer">${btn('Cancel','close')}<button class="primary" type="submit">Save settings</button></div></form>`);}
function ask(q){chat.push({role:'user',text:q},{role:'assistant',text:answer(q)});go('assistant');}
function reportRows(){const v=current();if(reportType==='management')return metrics.map(m=>({line_item:m.name,period,range:mode,currency:data.currency,amount:metricValue(v,m.id),unit:m.format}));return (reportType==='balance'?balanceRows:reportType==='cash'?cashRows:incomeRows).map(([label,k])=>({line_item:label,period,range:mode,currency:data.currency,amount:v[k]}));}
function audit(s){data.audit.unshift({at:new Date().toISOString(),action:s});}
function handleAction(action,el){const id=el.dataset.id,kind=el.dataset.kind;switch(action){case 'go':go(id);break;case 'close':close();break;case 'metric':metricModal(id);break;case 'statement':statement=id;render();break;case 'report-type':reportType=id;render();break;case 'invoice':invoiceModal(id);break;case 'payment':paymentModal(id);break;case 'add-invoice':invoiceForm(kind);break;case 'settings':settingsModal();break;case 'search':modal('Find a financial metric',`<input id="global-search" class="search-field" placeholder="Search metrics…" aria-label="Search all metrics"><div id="search-results">${metrics.slice(0,8).map(m=>btn(m.name,'metric',`data-id="${m.id}"`,'suggestion')).join('')}</div>`);$('#global-search').focus();break;case 'export-view':download(`InsightX-${route}-${period}.csv`,csv(metrics.map(m=>({metric:m.name,period,range:mode,currency:data.currency,value:metricValue(current(),m.id),unit:m.format,formula:m.formula}))));toast('KPI report downloaded.');break;case 'export-ledger':download(`InsightX-${kind}.csv`,csv(data.invoices.filter(x=>x.kind===kind)));break;case 'export-invoice':download(`${id}.csv`,csv([data.invoices.find(x=>x.id===id)]));break;case 'export-metric':{const m=metricBy(id);download(`InsightX-${id}.csv`,csv(data.months.map(x=>({month:x.month,metric:m.name,value:metricValue(calculate(data,x.month),id),unit:m.format,currency:data.currency}))));break;}case 'export-forecast':download('InsightX-forecast.csv',csv(forecast(data,scenario)));break;case 'save-scenario':data.scenario={...scenario};audit('Saved forecast scenario');toast('Scenario saved in this session. Include it in a backup to keep it.');break;case 'reset-scenario':scenario={growth:5,cost:2,collectionDays:35};render();toast('Default assumptions restored.');break;case 'add-task':{const x=getInsights().find(x=>x.id===id);if(x&&!data.tasks.some(t=>t.key===id)){data.tasks.push({id:'task-'+Date.now(),key:id,title:x.title,owner:x.owner,done:false});audit('Added action: '+x.title);}render();toast('Added to your action plan.');break;}case 'export-tasks':download('InsightX-action-plan.csv',csv(data.tasks));break;case 'ask':ask(el.dataset.question);break;case 'clear-chat':chat=[];render();break;case 'print':window.print();break;case 'export-report':download(`InsightX-${reportType}-${period}.csv`,csv(reportRows()));break;case 'save-report':data.savedReports.unshift({id:'report-'+Date.now(),name:`${reportType} · ${monthName(period)} · ${mode}`,created:new Date().toLocaleString(),rows:reportRows()});render();toast('Snapshot saved in this session.');break;case 'download-snapshot':{const r=data.savedReports.find(x=>x.id===id);download('InsightX-snapshot.csv',csv(r.rows));break;}case 'backup':download('InsightX-workspace.json',JSON.stringify({...data,scenario},null,2),'application/json');toast('Workspace backup downloaded.');break;case 'restore':importModal('restore');break;case 'import-months':importModal('months');break;case 'import-ledger':importModal('ledger');break;case 'template-months':download('InsightX-monthly-template.csv',csv(sampleData().months));break;case 'template-ledger':download('InsightX-ledger-template.csv',csv(sampleData().invoices));break;case 'export-audit':download('InsightX-activity.csv',csv(data.audit.length?data.audit:[{at:'',action:'No activity'}]));break;case 'column-guide':modal('Monthly CSV column guide',`<p>Amounts are in your selected reporting currency. Use positive expenses and outflows. No thousands separators inside numeric fields. Dates use YYYY-MM.</p><div class="table-wrap"><table><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody>${numericFields.map(k=>`<tr><td>${k}</td><td>${esc(({cash_open:'Beginning cash; must match prior month closing cash',ar:'Closing customer receivables',ap:'Closing supplier payables',opex:'Operating expenses, including marketing, excluding depreciation',collections:'Cash collected from customers',supplier_payments:'Cash paid to suppliers',operating_payments:'Cash operating expenses paid',equity:'Reported closing equity; assets must equal liabilities plus equity',marketing_spend:'Marketing portion already included in OPEX',net_fixed_assets:'Closing fixed assets net of accumulated depreciation',income_tax:'Recorded income tax expense; no tax rate is calculated',customers:'Active customers in the month',budget_cogs:'Direct cost budget'})[k]||k.replaceAll('_',' '))}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">Revenue and expenses are accrual figures; cash-flow fields are actual cash movements. The template includes an illustrative balanced dataset.</p>`);break;case 'reset':modal('Reset the workspace?',`<p>This replaces all session edits with the sample company. Download a backup first if you need to keep your work.</p><div class="modal-footer">${btn('Download backup','backup')}${btn('Cancel','close')}${btn('Reset to sample','confirm-reset','','primary')}</div>`);break;case 'confirm-reset':data=sampleData();period=data.months.at(-1).month;scenario={...data.scenario};chat=[];close();render();toast('Sample company restored.');break;case 'confirm-import':commitImport();break;}}
function commitImport(){if(!pendingImport)return;const p=pendingImport;if(p.type==='months'){data.months=p.rows;data.invoices=[];data.ledgerMatched=p.rows.at(-1).ar===0&&p.rows.at(-1).ap===0;data.asOf=iso(endDate(p.rows.at(-1).month));data.source='Imported monthly CSV';data.tasks=[];data.savedReports=[];data.audit=[];chat=[];}else if(p.type==='ledger'){data.invoices=p.rows;data.ledgerMatched=true;}else{data=p.data;scenario={...data.scenario};chat=[];}period=data.months.at(-1).month;audit(`Imported ${p.type==='restore'?'workspace backup':p.type+' CSV'}: ${p.filename}`);close();render();toast('Validated data loaded. All financial calculations updated.');}
async function submit(form){const fd=new FormData(form);try{switch(form.id){case 'payment-form':recordPayment(data,form.dataset.id,Number(fd.get('amount')));close();render();toast('Entry recorded. Cash and balances updated.');break;case 'invoice-form':addInvoice(data,{id:String(fd.get('id')).trim(),party:String(fd.get('party')).trim(),kind:form.dataset.kind,amount:Number(fd.get('amount')),issued:String(fd.get('issued')),due:String(fd.get('due')),notes:String(fd.get('notes'))});close();render();toast('Entry added to ledger and financial statements.');break;case 'scenario-form':scenario={growth:Number(fd.get('growth')),cost:Number(fd.get('cost')),collectionDays:Number(fd.get('collectionDays'))};render();toast('Forecast recalculated.');break;case 'budget-form':{const m=data.months.find(x=>x.month===period);for(const k of ['budget_revenue','budget_cogs','budget_opex']){const n=Number(fd.get(k));if(!Number.isFinite(n)||n<0)throw new Error('Budgets must be non-negative numbers.');m[k]=n;}audit('Updated budget for '+period);render();toast('Monthly budget updated.');break;}case 'chat-form':{const q=String(fd.get('question')).trim();if(q)ask(q);break;}case 'settings-form':{const name=String(fd.get('company')).trim();if(!name)throw new Error('Enter a company name.');data.company=name;data.currency=String(fd.get('currency'));audit('Updated company reporting settings');close();render();toast('Company settings saved.');break;}case 'import-form':{const file=fd.get('file');if(!file||!file.size)throw new Error('Choose a non-empty file.');if(file.size>5*1024*1024)throw new Error('File exceeds 5 MB.');const text=await file.text(),type=form.dataset.type;let summary='';if(type==='months'){const rows=validateMonths(parseCSV(text));pendingImport={type,rows,filename:file.name};summary=`${rows.length} monthly records · ${rows[0].month} to ${rows.at(-1).month}. Monthly figures, ledger detail, action plan, report snapshots and activity will be replaced. You can import a matching ledger afterward.`;}else if(type==='ledger'){const rows=validateInvoices(parseCSV(text),data.months);pendingImport={type,rows,filename:file.name};summary=`${rows.length} ledger entries. Outstanding balances match the latest monthly financial data. Existing ledger detail will be replaced.`;}else{const backup=JSON.parse(text);if(backup.version!==1)throw new Error('Unsupported workspace backup version.');const months=validateMonths(backup.months);const invoices=backup.ledgerMatched===false?[]:validateInvoices(backup.invoices,months);if(typeof backup.company!=='string'||!backup.company.trim()||backup.company.length>80||!['SAR','USD','AED','EUR','GBP'].includes(backup.currency))throw new Error('Backup company settings are invalid.');const sc=backup.scenario;if(!sc||!Number.isFinite(sc.growth)||sc.growth< -30||sc.growth>30||!Number.isFinite(sc.cost)||sc.cost< -20||sc.cost>30||!Number.isFinite(sc.collectionDays)||sc.collectionDays<0||sc.collectionDays>90)throw new Error('Invalid forecast assumptions.');if(!Array.isArray(backup.tasks)||!Array.isArray(backup.savedReports)||!Array.isArray(backup.audit))throw new Error('Invalid backup records.');for(const t of backup.tasks)if(typeof t.id!=='string'||typeof t.title!=='string'||typeof t.owner!=='string'||typeof t.done!=='boolean')throw new Error('Invalid action-plan entry.');for(const r of backup.savedReports)if(typeof r.id!=='string'||typeof r.name!=='string'||typeof r.created!=='string'||!Array.isArray(r.rows))throw new Error('Invalid report snapshot.');for(const a of backup.audit)if(typeof a.at!=='string'||typeof a.action!=='string')throw new Error('Invalid activity entry.');pendingImport={type,filename:file.name,data:{...backup,months,invoices,asOf:iso(endDate(months.at(-1).month)),source:typeof backup.source==='string'?backup.source:'Restored workspace'}};summary=`${backup.company} · ${months.length} months · ${invoices.length} ledger entries. Restoring replaces this entire session.`;}modal('Review validated import',`<p><b>${esc(file.name)}</b></p><p>${esc(summary)}</p><p class="notice">Validation passed: dates, required values, cash continuity and balance-sheet reconciliation.</p><div class="modal-footer">${btn('Cancel','close')}${btn('Replace current data','confirm-import','','primary')}</div>`);break;}}
}catch(error){if($('#form-error'))$('#form-error').innerHTML=`<p class="error">${esc(error.message)}</p>`;else toast(error.message);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();handleAction(b.dataset.action,b);}});
document.addEventListener('submit',e=>{e.preventDefault();submit(e.target);});
document.addEventListener('change',e=>{if(e.target.id==='period'){period=e.target.value;render();}if(e.target.id==='mode'){mode=e.target.value;render();}if(e.target.id==='ledger-filter'){ledgerFilter=e.target.value;render();}if(e.target.id==='kpi-group'){kpiGroup=e.target.value;render();}if(e.target.dataset.task){const t=data.tasks.find(x=>x.id===e.target.dataset.task);t.done=e.target.checked;audit((t.done?'Completed: ':'Reopened: ')+t.title);render();}});
document.addEventListener('input',e=>{const id=e.target.id;if(['growth','cost','collectionDays'].includes(id))$('#out-'+id).textContent=e.target.value+e.target.dataset.unit;if(id==='global-search'){const q=e.target.value.toLowerCase();$('#search-results').innerHTML=metrics.filter(m=>`${m.name} ${m.id}`.toLowerCase().includes(q)).map(m=>btn(m.name,'metric',`data-id="${m.id}"`,'suggestion')).join('')||'<p class="muted">No matching metric.</p>';}if(id==='kpi-search'||id==='ledger-search'){const start=e.target.selectionStart;query=e.target.value;render();const input=$('#'+id);input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();handleAction('search',{dataset:{}});}if(e.key==='Escape'&&!$('#overlay').hidden)close();if(e.key==='Tab'&&!$('#overlay').hidden){const nodes=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))close();});$('#menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));window.addEventListener('hashchange',()=>{query='';render();window.scrollTo(0,0);});
render();
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_finance_metrics',description:'Read calculated SME financial KPIs for the selected period without changing data.',inputSchema:{type:'object',properties:{metricIds:{type:'array',items:{type:'string'}}},required:['metricIds'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!Array.isArray(input.metricIds)||!input.metricIds.length||input.metricIds.some(id=>!metricBy(id)))throw new Error('Provide valid metric IDs from the KPI library.');return {company:data.company,period,range:mode,currency:data.currency,metrics:input.metricIds.map(id=>({id,name:metricBy(id).name,value:metricValue(current(),id),unit:metricBy(id).format}))};}},{name:'navigate_finance_section',description:'Open a finance section. Does not modify financial records.',inputSchema:{type:'object',properties:{section:{type:'string',enum:links.map(x=>x[0])}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!links.some(x=>x[0]===input.section))throw new Error('Unknown finance section.');history.replaceState(null,'','#'+input.section);render();return {section:route};}},{name:'configure_cash_scenario',description:'Recalculate the visible three-month cash scenario. Does not save or change accounting data.',inputSchema:{type:'object',properties:{growth:{type:'number',minimum:-30,maximum:30},cost:{type:'number',minimum:-20,maximum:30},collectionDays:{type:'number',minimum:0,maximum:90}},required:['growth','cost','collectionDays'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(![input.growth,input.cost,input.collectionDays].every(Number.isFinite)||input.growth< -30||input.growth>30||input.cost< -20||input.cost>30||input.collectionDays<0||input.collectionDays>90)throw new Error('Invalid scenario assumptions.');scenario={growth:input.growth,cost:input.cost,collectionDays:input.collectionDays};history.replaceState(null,'','#budgets');render();return {assumptions:scenario,forecast:forecast(data,scenario)};}}];for(const def of definitions)try{Promise.resolve(context.registerTool(def,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
